 const panel=make('section','portal-plugin-setup'),bar=make('div','portal-plugin-bar'),clients=make('div','portal-plugin-clients'),modes=make('div','portal-plugin-modes');let client='Codex',mode='Plugin';
 const steps=make('div','portal-plugin-steps'),one=make('article'),two=make('article'),code=make('pre','portal-plugin-code'),status=make('p','portal-muted');status.setAttribute('role','status');
 const instructions=()=>`# VisualAgent ${client} 接入说明\n\n使用当前创作账户的 HTTP API。此接入说明不是已发布的 marketplace 插件。\n\n1. 让用户在账户中心创建独立访问密钥，在本地环境变量 VISUALAGENT_API_KEY 中配置；不要在聊天、命令输出或轨迹中显示密钥。\n2. API 根路径：${location.origin}/creative/api\n3. GET /models 读取实际支持的模型；GET /projects 读取当前账户项目；GET /projects/{id} 读取生成状态与画布。请求使用 Authorization: Bearer 环境变量中的密钥。\n4. POST /projects 创建草稿，creation_mode 为 image 或 video；不要提交 /message。\n5. 图片：POST /projects/{id}/images/preview 核验 model、prompt、references、revision 与 connect_to_director:false。用户确认一次生成后，POST /images 带相同输入和返回的 input_hash、独立 request_id、approved_credits。\n6. 视频：GET /projects/{id}/budget 核验费用。用户明确授权后 POST /execute，传 revision 与 approved_credits。\n7. 轮询 GET /projects/{id}，成功后在画布查看结果；失败停止，禁止更换模型或自动重试。\n8. 不记录凭据、供应商原始响应或临时媒体地址。`;
 const cli=()=>`# 在本地配置 VISUALAGENT_API_KEY 后，读取已接入模型\ncurl --fail --silent --show-error '${location.origin}/creative/api/models' \\\n  -H "Authorization: Bearer $VISUALAGENT_API_KEY"\n\n# 读取自己的项目（不触发生成）\ncurl --fail --silent --show-error '${location.origin}/creative/api/projects' \\\n  -H "Authorization: Bearer $VISUALAGENT_API_KEY"`;
