 two.append(make('span','portal-step','2'),make('h3','','连接账户，开始创作'),make('p','portal-muted','使用独立访问密钥，授权后由 Agent 创建素材。'),button('管理访问密钥',()=>{accountTab='tokens';showView('account')},'portal-white'),button('打开创作画布',()=>location.href='/creative?new=1','portal-text'),make('p','portal-plugin-note','图片、视频、项目状态与画布使用同一账户。Blender 插件尚未接入。'));
