 const examplesData=[['全模型调用生成','film','选择模型，生成一张图或一段视频','模型目录提供当前已接入的 Kling 图片与视频模型。生成任务显示真实状态，结果返回画布。','打开图片创作','/creative?new=1&tool=image'],['多资产管理提案','asset','把参考与结果放在同一画布','查看自己的项目资产，将商品、人物与场景图片作为明确的生成输入。','查看我的资产','?view=assets'],['可控多场景生成','cube','先预演场景，再制作镜头','在 3D-BOX 中调整场景和相机，确认后进入创作流程。','打开 3D-BOX','?view=scene']];
